#include <stdio.h>
int fib(int n) {
    if (n <= 1) return n;
    return fib(n - 1) + fib(n - 2);
}
int is_even(int n);
int is_odd(int n) {
    if (n == 0) return 0;
    return is_even(n - 1);
}
int is_even(int n) {
    if (n == 0) return 1;
    return is_odd(n - 1);
}
int main() {
    printf("fib(%d) = %d\n", 0, fib(0));
    printf("even(%d) = %d\n", 0, is_even(0));
    return 0;
}
